SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", (CAST(CASE WHEN (SUM(SUM(SPEND_IN_CURRENCY)) OVER ()) = 0 OR (SUM(SUM(SPEND_IN_CURRENCY)) OVER ()) IS NULL THEN NULL ELSE CAST((SUM(SPEND_IN_CURRENCY)) AS DECIMAL(38, 15)) / CAST((SUM(SUM(SPEND_IN_CURRENCY)) OVER ()) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "ORG_ACCOUNT_SPEND_SHARE" FROM (SELECT "ACCOUNT_NAME" AS ACCOUNT_NAME, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, "USAGE_TYPE" AS USAGE_TYPE, "CURRENCY" AS CURRENCY, (CAST("USAGE" AS DECIMAL(38, 9))) AS USAGE_UNITS, (CAST("USAGE_IN_CURRENCY" AS DECIMAL(38, 9))) AS SPEND_IN_CURRENCY FROM usage_in_currency_daily) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "ORG_ACCOUNT_SPEND_SHARE" DESC, "TIME_BUCKET" LIMIT 100
